/**
 * The webapp's view of the api contract, generated from the server.
 *
 * Every type below is an alias into `openapi.d.ts`, which `npm run api:types`
 * generates from `backend/openapi.json` -- itself generated from the zod
 * schemas the routes answer with. So a shape here cannot disagree with what
 * the server sends without the server having been changed first, which is the
 * whole reason this file is not hand-written.
 *
 * `openapi.d.ts` is **not** committed: it is regenerated by `postinstall`,
 * `predev`, `prebuild` and `pretypecheck`, so a stale copy cannot survive
 * anything you would run before noticing. `openapi.json` is committed, and CI
 * regenerates it and fails if the result differs.
 *
 * Aliases rather than deep paths at the call sites, for two reasons: the
 * generated names
 * (`operations['getApiDb']['responses'][200]['content']['application/json']`)
 * are unreadable in an error message, and one alias per endpoint is the only
 * place to change when an operationId does.
 */
import type { operations } from './openapi';

/**
 * The json body of a 200.
 *
 * `never` when the operation has no such response, which fails loudly here
 * rather than quietly at the call site.
 */
type Ok<K extends keyof operations> = operations[K]['responses'] extends {
  200: { content: { 'application/json': infer T } };
}
  ? T
  : never;

type Err<K extends keyof operations, S extends number> =
  operations[K]['responses'] extends Record<
    S,
    { content: { 'application/json': infer T } }
  >
    ? T
    : never;

/**
 * What `GET /api/db` reports: the MySQL instance of **this** environment.
 *
 * `readOnly` is true everywhere but test, and is what lets the ui say why the
 * buttons are dead -- `canStart`/`canStop` being false alone is
 * indistinguishable from the instance being mid-transition.
 */
export type DbState = Ok<'getApiDb'>;

/**
 * The body of any error the api answers with. One shape for every status, so
 * a failed fetch can be read without knowing which route it was.
 */
export type ApiError = Err<'postApiDbStart', 403>;
